insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('1', 'Idea & Validation', '2026-07-10 17:55:46.360166+00', 'Rob Fitzpatrick', 'FW-001', 'The Mom Test', 'Referenced in intervention for ''Lack of Customer Discovery'' and ''No Validation.'' Used as the primary tool for customer interview structure in the Question Bank.', '["all"]', '["INT-019"]', '["RC-001", "RC-002", "RC-003"]', 'Founders getting false validation from biased interviews — especially from friends and family who say ''great idea'' without meaning it.', 'The Mom Test — Rob Fitzpatrick (2013)', '[1, 2, 3]', '2026-07-10 17:55:46.360166+00', 'A customer interview framework that teaches founders how to ask questions that reveal the truth — not the answers people think you want to hear. Focuses on asking about past behaviour rather than future intentions.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('2', 'Idea & Validation', '2026-07-10 17:55:46.360166+00', 'Ash Maurya', 'FW-002', 'Lean Canvas', 'Used in intervention for ''Building Before Problem Framing.'' Recommended as the first structured planning tool before any development begins.', '["all"]', '["INT-021"]', '["RC-001", "RC-002", "RC-003"]', 'Founders building without a clear problem-solution hypothesis. Prevents the common mistake of building a solution before validating the problem.', 'Running Lean — Ash Maurya (2012)', '[1, 2]', '2026-07-10 17:55:46.360166+00', 'A one-page business plan template that focuses on problems, solutions, key metrics, and unfair advantages. A simplified, action-focused version of the Business Model Canvas designed for early-stage startups.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('3', 'Idea & Validation', '2026-07-10 17:55:46.360166+00', 'Clayton Christensen', 'FW-003', 'Jobs-To-Be-Done (JTBD)', 'Referenced across multiple root cause mappings. Used in the Agent Interpretation Table to probe beneath surface statements like ''customers don''t understand our product.''', '["all"]', '["INT-078"]', '["RC-001", "RC-002", "RC-003"]', 'Founders building products around features rather than customer progress. Reveals what the customer actually values versus what the founder assumes they value.', 'Competing Against Luck — Clayton Christensen (2016)', '[1, 2, 3, 4]', '2026-07-10 17:55:46.360166+00', 'A framework that reframes customer needs around the progress the customer is trying to make — the ''job'' they are hiring a product to do. Separates functional, emotional, and social jobs.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('4', 'Idea & Validation', '2026-07-10 17:55:46.360166+00', 'Strategyzer', 'FW-004', 'Assumption Mapping', 'Recommended in intervention for ''Building Before Problem Framing.'' Helps founders identify their riskiest assumption before writing a single line of code.', '["all"]', '["INT-040", "INT-021"]', '["RC-001", "RC-002", "RC-003"]', 'Founders building on unvalidated assumptions without realising which ones are most dangerous to the business if wrong.', 'Testing Business Ideas — Strategyzer (2019)', '[1, 2, 3]', '2026-07-10 17:55:46.360166+00', 'A structured method to identify and prioritise the assumptions in a business model by risk level. Maps assumptions on two axes: how important they are to the business and how much evidence exists for them.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('5', 'Idea & Validation', '2026-07-10 17:55:46.360166+00', 'Eric Ries / Lean Startup community', 'FW-005', 'Smoke Test / Landing Page Test', 'Recommended as an immediate next step in the intervention for ''No Real Market Need.'' The cheapest and fastest way to test demand with real behaviour rather than opinion.', '["all"]', '["INT-001"]', '["RC-001", "RC-002", "RC-003"]', 'Founders investing months of development before knowing whether anyone actually wants the product.', 'The Lean Startup — Eric Ries (2011)', '[1, 2]', '2026-07-10 17:55:46.360166+00', 'A pre-launch validation method where a founder builds a minimal landing page describing the product and measures real interest through sign-ups, clicks, or pre-orders — before building anything.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('6', 'Idea & Validation', '2026-07-10 17:55:46.360166+00', 'Eric Ries', 'FW-006', 'Build-Measure-Learn Loop', 'Referenced throughout the Question Bank and Intervention Library. Used as the guiding principle for any root cause involving ''over-engineering'' or ''lack of feedback loop.''', '["all"]', '["INT-020", "INT-011"]', '["RC-001", "RC-002", "RC-003"]', 'Founders spending too long building before getting feedback. Reduces the cost of being wrong by shortening the feedback cycle.', 'The Lean Startup — Eric Ries (2011)', '[1, 2, 3, 4]', '2026-07-10 17:55:46.360166+00', 'The core cycle of the Lean Startup methodology. Build the smallest possible version of an idea, measure how real users respond, learn from the data, and repeat. The loop replaces the traditional build-then-launch approach.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('7', 'Idea & Validation', '2026-07-10 17:55:46.360166+00', 'Founder Ally / GoXL', 'FW-007', 'Problem Ranking Matrix', 'Used in the intervention for ''Poor Problem Selection.'' The ranking matrix is one of the three immediate next steps recommended to founders struggling with problem selection.', '["all"]', '["INT-019"]', '["RC-001", "RC-002", "RC-003"]', 'Founders choosing a problem based on personal interest rather than market opportunity. Creates an objective basis for problem selection.', 'Founder Ally Intervention Library — Doc 8', '[1, 2]', '2026-07-10 17:55:46.360166+00', 'A structured evaluation tool for ranking multiple potential problems by urgency, frequency, willingness to pay, and market size. Helps founders choose which problem to solve first when multiple options exist.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('8', 'Idea & Validation', '2026-07-10 17:55:46.360166+00', 'Teresa Torres', 'FW-008', 'Opportunity Solution Tree', 'Referenced in the intervention for ''Building Before Problem Framing'' and ''No Clear Product Vision.'' Used to structure how Founder Ally frames the relationship between root causes and interventions.', '["all"]', '["INT-019"]', '["RC-001", "RC-002", "RC-003"]', 'Founders who jump from problem straight to solution without understanding the full opportunity space. Prevents premature solution commitment.', 'Continuous Discovery Habits — Teresa Torres (2021)', '[1, 2, 3, 4]', '2026-07-10 17:55:46.360166+00', 'A visual framework that separates desired outcomes, customer opportunities, and potential solutions. Forces founders to start with what the customer needs to achieve before jumping to solutions.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('9', 'Idea & Validation', '2026-07-10 17:55:46.360166+00', 'Alberto Savoia', 'FW-009', 'Pretotype Framework', 'Used in intervention for ''Over-Engineering and Perfectionism.'' Recommended as an alternative to building when founders are trapped in perfectionism.', '["all"]', '["INT-040"]', '["RC-001", "RC-002", "RC-003"]', 'Founders building full prototypes before validating that anyone will actually use the product. ''Build the right it before you build it right.''', 'Pretotype It — Alberto Savoia (2011)', '[1, 2]', '2026-07-10 17:55:46.360166+00', 'A validation method that tests whether the right people will use the right product in the right context — before building a full prototype. Uses the minimum possible effort to validate real interest.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('10', 'Idea & Validation', '2026-07-10 17:55:46.360166+00', 'Founder Ally / GoXL synthesis', 'FW-010', 'Willingness-to-Pay Interview', 'Recommended in interventions for ''Neglecting Pricing Strategy'' and ''Pricing and Unit-Economics Confusion.'' One of the three immediate next steps for pricing root causes.', '["all"]', '["INT-001"]', '["RC-001", "RC-002", "RC-003"]', 'Founders pricing by gut feeling or competitor copying rather than real customer data. The most reliable way to discover what customers will actually pay.', 'Founder Ally Intervention Library — Doc 8', '[1, 2, 3, 4]', '2026-07-10 17:55:46.360166+00', 'A structured customer interview technique focused specifically on pricing. Asks customers directly about price sensitivity, acceptable ranges, and what would make them switch to or from a solution.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('11', 'Go-To-Market', '2026-07-10 17:55:46.360166+00', 'Founder Ally / GoXL synthesis', 'FW-011', 'ICP Builder (Ideal Customer Profile)', 'Directly feeds the onboarding question ''Who is your ideal customer?'' Used in the root cause assessment for GTM failures and weak pipeline. One of the most referenced frameworks in Founder Ally.', '["all"]', '["INT-003"]', '["RC-073", "RC-074", "RC-075"]', 'Founders targeting too broadly or defining customers by vague characteristics like ''SMBs in India.'' Precision targeting reduces wasted sales and marketing effort.', 'Founder Ally Intervention Library — Doc 8 / Doc 9', '[2, 3, 4, 5]', '2026-07-10 17:55:46.360166+00', 'A structured framework for defining the ideal customer using firmographics, psychographics, behaviours, pain severity, and trigger events. Goes beyond basic demographics to identify customers most likely to buy, stay, and refer.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('12', 'Go-To-Market', '2026-07-10 17:55:46.360166+00', 'Geoffrey Moore', 'FW-012', 'Beachhead Market Strategy', 'Referenced in interventions for ''Undefined ICP'' and ''Wrong GTM.'' Used as the primary recommendation when the root cause is ''fear of missing customers'' or overly broad targeting.', '["all"]', '["INT-003", "INT-018"]', '["RC-073", "RC-074", "RC-075"]', 'Founders trying to serve everyone at once and serving no one well. Concentrating resources on one beachhead creates a repeatable success pattern before scaling.', 'Crossing the Chasm — Geoffrey Moore (1991)', '[1, 2, 3, 4]', '2026-07-10 17:55:46.360166+00', 'A market entry strategy where the founder picks one very narrow segment to dominate completely before expanding. Named after the military tactic of securing a small beach position before advancing inland.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('13', 'Go-To-Market', '2026-07-10 17:55:46.360166+00', 'Gabriel Weinberg & Justin Mares', 'FW-013', 'Bullseye Framework', 'Used in intervention for ''Wrong or Untested Channels.'' The Bullseye is the recommended first tool for any founder whose root cause involves channel assumptions or untested channel investments.', '["all"]', '["INT-023"]', '["RC-073", "RC-074", "RC-075"]', 'Founders choosing channels based on what is trendy rather than what works for their specific business. Creates a data-driven basis for channel investment.', 'Traction — Gabriel Weinberg & Justin Mares (2014)', '[2, 3, 4]', '2026-07-10 17:55:46.360166+00', 'A systematic channel testing framework where founders test all 19 possible traction channels through three concentric circles — outer (all channels), middle (top 6), inner (best 3) — narrowing to the most effective.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('14', 'Go-To-Market', '2026-07-10 17:55:46.360166+00', 'April Dunford', 'FW-014', 'Obviously Awesome Positioning Framework', 'Referenced in intervention for ''Poor Positioning & Messaging.'' Used in the Agent Interpretation Table to probe beneath statements like ''customers don''t get what we do.''', '["all"]', '["INT-004"]', '["RC-073", "RC-074", "RC-075"]', 'Founders with weak or confusing positioning — products that sound like everything else or mean nothing to the customer. Positioning failure is one of the top causes of GTM and messaging failure.', 'Obviously Awesome — April Dunford (2019)', '[2, 3, 4, 5]', '2026-07-10 17:55:46.360166+00', 'A 5-step framework for defining competitive positioning: identify competitive alternatives, isolate unique attributes, define the value these attributes enable, identify target customers who care most about this value, and name the market category.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('15', 'Go-To-Market', '2026-07-10 17:55:46.360166+00', 'Alexander Osterwalder', 'FW-015', 'Value Proposition Canvas', 'Used in interventions for ''Poor Positioning,'' ''No Product-Market Fit,'' and ''Sacrificing User Needs for Monetisation.'' One of the most versatile frameworks in the Founder Ally library.', '["all"]', '["INT-004", "INT-043", "INT-081"]', '["RC-073", "RC-074", "RC-075"]', 'Founders building products that do not match what the customer cares about. The Value Proposition Canvas makes the fit — or the gap — visible.', 'Value Proposition Design — Osterwalder et al. (2014)', '[1, 2, 3, 4]', '2026-07-10 17:55:46.360166+00', 'A tool for ensuring the product creates value for customers by mapping customer jobs, pains, and gains against the product''s pain relievers and gain creators. Ensures the product actually fits what the customer needs.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('16', 'Go-To-Market', '2026-07-10 17:55:46.360166+00', 'Dave McClure', 'FW-016', 'AARRR Funnel (Pirate Metrics)', 'Referenced in interventions for ''Over-Focusing on Acquisition'' and ''Ignoring Retention.'' Used in the scoring engine to weight GTM questions toward the appropriate funnel stage.', '["saas", "manufacturing"]', '["INT-026", "INT-023"]', '["RC-073", "RC-074", "RC-075"]', 'Founders obsessing over acquisition while ignoring retention and activation. The AARRR framework forces attention across the entire customer lifecycle.', 'Dave McClure / 500 Startups (2007)', '[3, 4, 5, 6]', '2026-07-10 17:55:46.360166+00', 'A framework that breaks the growth funnel into five stages: Acquisition, Activation, Retention, Referral, and Revenue. Helps founders identify where in the funnel their biggest growth leaks are.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('17', 'Go-To-Market', '2026-07-10 17:55:46.360166+00', 'CX Design community', 'FW-017', 'Customer Journey Mapping', 'Referenced in interventions for ''Confusing GTM with Marketing'' and ''Poor User Experience.'' Used in the diagnosis to probe whether founders understand their customer''s buying journey.', '["all"]', '["INT-080", "INT-022", "INT-041"]', '["RC-073", "RC-074", "RC-075"]', 'Founders designing products and GTM from the inside out — based on what they think the customer experience is, not what it actually is.', 'Founder Ally Intervention Library — Doc 8', '[2, 3, 4, 5]', '2026-07-10 17:55:46.360166+00', 'A visual representation of every interaction a customer has with the business from first awareness through purchase and beyond. Reveals friction points, gaps, and opportunities the founder cannot see from the inside.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('18', 'Go-To-Market', '2026-07-10 17:55:46.360166+00', 'Winning by Design', 'FW-018', 'Bowtie Model', 'Referenced in interventions for ''Over-Focusing on Acquisition'' and ''Losing Customers Costs More Than It Looks.'' Used in the SaaS and Services industry calibration layers.', '["saas", "services"]', '["INT-059", "INT-022"]', '["RC-073", "RC-074", "RC-075"]', 'Founders treating revenue as a funnel that ends at purchase rather than a cycle that continues through retention and expansion.', 'Winning by Design / Jacco van der Kooij', '[4, 5, 6, 7]', '2026-07-10 17:55:46.360166+00', 'A revenue model that treats the customer lifecycle as a bowtie — acquisition and conversion on the left, expansion and advocacy on the right, with retention at the centre knot. Balances new customer growth with existing customer growth.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('19', 'Go-To-Market', '2026-07-10 17:55:46.360166+00', 'Founder Ally / GoXL synthesis', 'FW-019', 'Go-to-Market Strategy Canvas', 'Used in intervention for ''Confusing GTM with Marketing.'' The canvas is recommended as the first structured exercise before any marketing spend is committed.', '["all"]', '["INT-022"]', '["RC-073", "RC-074", "RC-075"]', 'Founders who build a marketing plan but not a GTM strategy — missing the commercial architecture needed to actually acquire and retain customers at scale.', 'Founder Ally Intervention Library — Doc 8', '[2, 3, 4, 5]', '2026-07-10 17:55:46.360166+00', 'A one-page framework that aligns ICP, value proposition, pricing, channels, sales motion, and success metrics into a single coherent GTM plan. Prevents the common mistake of treating GTM as just marketing.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('20', 'Sales & Revenue', '2026-07-10 17:55:46.360166+00', 'Jack Napoli & Dick Dunkel', 'FW-020', 'MEDDIC', 'Referenced in intervention for ''Weak Pipeline / No Deals.'' Used in the Question Bank for sales category probing questions about deal qualification and pipeline health.', '["all"]', '[]', '["RC-155", "RC-156", "RC-157"]', 'Founders wasting sales time on unqualified leads that will never close. MEDDIC creates a structured basis for qualification that removes optimism bias.', 'PTC Corporation sales methodology (1990s)', '[3, 4, 5, 6]', '2026-07-10 17:55:46.360166+00', 'A B2B sales qualification framework: Metrics (economic impact), Economic Buyer (who controls budget), Decision Criteria (how they decide), Decision Process (how the decision is made), Identify Pain (core problem), Champion (internal advocate). Ensures only qualified deals enter the pipeline.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('21', 'Sales & Revenue', '2026-07-10 17:55:46.360166+00', 'Neil Rackham', 'FW-021', 'SPIN Selling', 'Referenced in intervention for ''Inability to Close Deals.'' Used in the Question Bank to design probing questions that mirror the SPIN structure in the diagnosis flow.', '["all"]', '["INT-006"]', '["RC-155", "RC-156", "RC-157"]', 'Founders who pitch their product too early before understanding the customer''s problem deeply enough. SPIN replaces pitching with structured discovery.', 'SPIN Selling — Neil Rackham (1988)', '[2, 3, 4, 5]', '2026-07-10 17:55:46.360166+00', 'A research-based sales methodology using four question types: Situation (context), Problem (pain points), Implication (consequences of the problem), Need-Payoff (value of solving it). Based on research into 35,000 sales calls.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('22', 'Sales & Revenue', '2026-07-10 17:55:46.360166+00', 'Matthew Dixon & Brent Adamson', 'FW-022', 'Challenger Sale Framework', 'Referenced in intervention for ''Inability to Close Deals.'' Recommended when the root cause is weak discovery skills or product-centric selling.', '["all"]', '["INT-006"]', '["RC-155", "RC-156", "RC-157"]', 'Founders who rely on relationship selling or product demonstrations without challenging the customer''s thinking. Works especially well for complex B2B sales.', 'The Challenger Sale — Dixon & Adamson (2011)', '[3, 4, 5, 6]', '2026-07-10 17:55:46.360166+00', 'A sales approach where the salesperson teaches the customer something they do not know, tailors the message to their specific context, and takes control of the conversation. Based on research into what top salespeople do differently.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('23', 'Sales & Revenue', '2026-07-10 17:55:46.360166+00', 'Hans van Westendorp', 'FW-023', 'Van Westendorp Price Sensitivity Meter', 'Referenced in intervention for ''Neglecting Pricing Strategy.'' Recommended when the root cause is ''pricing below market value'' or ''pricing without data.''', '["all"]', '["INT-024"]', '["RC-155", "RC-156", "RC-157"]', 'Founders pricing by gut feeling, cost-plus calculation, or competitor copying. Van Westendorp provides empirical data on what customers will actually pay.', 'Hans van Westendorp (1976)', '[1, 2, 3, 4, 5]', '2026-07-10 17:55:46.360166+00', 'A customer research method using four questions to establish acceptable price ranges: too cheap (quality concerns), cheap but acceptable, expensive but acceptable, too expensive. Creates price sensitivity curves from real customer data.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('24', 'Sales & Revenue', '2026-07-10 17:55:46.360166+00', 'Thomas Nagle', 'FW-024', 'Value-Based Pricing Framework', 'Referenced across multiple interventions for pricing root causes. The primary pricing framework recommended in Doc 9 (Industry Classification) for all 4 verticals.', '["all"]', '["INT-024", "INT-057"]', '["RC-155", "RC-156", "RC-157"]', 'Founders chronically underpricing because they price on cost rather than value. Especially common in Indian market where cost-plus pricing is the default assumption.', 'The Strategy and Tactics of Pricing — Thomas Nagle', '[2, 3, 4, 5, 6]', '2026-07-10 17:55:46.360166+00', 'A pricing methodology that sets prices based on the customer''s perceived value of the outcome — not the cost of production or what competitors charge. Requires understanding of the economic benefit the customer receives.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('25', 'Sales & Revenue', '2026-07-10 17:55:46.360166+00', 'Lincoln Murphy / Gainsight', 'FW-025', 'Customer Success Framework', 'Referenced in interventions for ''Over-Discounting or Churn'' and ''Chasing New Customers vs Keeping Old Ones.'' Used heavily in the SaaS and Services industry calibration layers.', '["all"]', '["INT-080", "INT-029"]', '["RC-155", "RC-156", "RC-157"]', 'Founders treating customer success as customer support — reactive instead of proactive. Churn is almost always a customer success failure, not a product failure.', 'Customer Success — Nick Mehta et al. (2016)', '[4, 5, 6, 7]', '2026-07-10 17:55:46.360166+00', 'A structured approach to ensuring customers achieve their desired outcomes with the product. Covers onboarding, adoption, health monitoring, renewal, and expansion — treating customer success as a proactive function, not reactive support.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('26', 'Sales & Revenue', '2026-07-10 17:55:46.360166+00', 'SaaS industry standard', 'FW-026', 'SaaS Unit Economics Framework', 'Directly feeds the SaaS industry calibration in Doc 9. Used in the Question Bank for financial health probing. The red flag thresholds from this framework power the SaaS industry diagnostic adjustments.', '["saas"]', '["INT-027"]', '["RC-155", "RC-156", "RC-157"]', 'SaaS founders who cannot answer basic unit economics questions — growing revenue while destroying value. These metrics are the vital signs of a SaaS business.', 'SaaS industry standard / David Skok / OpenView Partners', '[3, 4, 5, 6, 7]', '2026-07-10 17:55:46.360166+00', 'A financial framework for measuring the health of a SaaS business through key metrics: Customer Acquisition Cost (CAC), Lifetime Value (LTV), LTV:CAC ratio, Gross Margin, Monthly Recurring Revenue (MRR), Net Revenue Retention (NRR), and Payback Period.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('27', 'Sales & Revenue', '2026-07-10 17:55:46.360166+00', 'Sales Hacker / Outreach community', 'FW-027', 'Outbound Cadence Design', 'Referenced in intervention for ''Weak Pipeline / No Deals.'' One of the three immediate next steps recommended for founders with a pipeline root cause.', '["all"]', '["INT-005"]', '["RC-155", "RC-156", "RC-157"]', 'Founders who do one outreach attempt and give up when there is no response. Research shows most B2B deals require 8-12 touchpoints before a response.', 'Sales Hacker / Outreach.io best practices', '[2, 3, 4, 5]', '2026-07-10 17:55:46.360166+00', 'A structured multi-touch outreach sequence that combines email, LinkedIn, phone, and content touches at specific intervals. Replaces random outreach with a systematic approach to building pipeline.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('28', 'Sales & Revenue', '2026-07-10 17:55:46.360166+00', 'SiriusDecisions / Forrester', 'FW-028', 'Revenue Operations (RevOps) Framework', 'Referenced in intervention for ''Too Many Revenue Streams to Track'' (Section 9.2 of Doc 8). Used in the Scaling & Operational Maturity category for Stage 6+ founders.', '["all"]', '["INT-056"]', '["RC-155", "RC-156", "RC-157"]', 'Scaling companies where sales, marketing, and customer success work in silos with different data and different goals — causing revenue leakage and customer friction.', 'SiriusDecisions / Forrester Research', '[6, 7, 8]', '2026-07-10 17:55:46.360166+00', 'A business function that integrates sales, marketing, customer success, and finance into one unified revenue system with shared data, processes, and accountability. Eliminates silos that cause revenue inefficiency.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('29', 'Product', '2026-07-10 17:55:46.360166+00', 'Intercom', 'FW-029', 'RICE Prioritisation Framework', 'Referenced in intervention for ''Feature Bloat.'' The primary prioritisation tool recommended when the root cause is ego-driven development or customer-pleasing behaviour.', '["saas"]', '["INT-012"]', '["RC-373", "RC-374", "RC-375"]', 'Founders who build features based on whoever asked loudest or what sounds exciting — without a systematic way to evaluate trade-offs.', 'Intercom — Sean McBride (2016)', '[3, 4, 5, 6, 7]', '2026-07-10 17:55:46.360166+00', 'A product prioritisation scoring model: Reach (how many users affected), Impact (how much it moves the needle), Confidence (how sure we are), divided by Effort (how much work). Creates an objective ranking of features and projects.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('30', 'Product', '2026-07-10 17:55:46.360166+00', 'Noriaki Kano', 'FW-030', 'Kano Model', 'Referenced in interventions for ''Feature Bloat'' and ''Sacrificing User Needs for Monetisation.'' Used in the diagnosis to probe whether founders understand what their customers truly value.', '["all"]', '["INT-043", "INT-012"]', '["RC-373", "RC-374", "RC-375"]', 'Founders adding features that do not improve satisfaction or remove features that customers take for granted. The Kano Model reveals the difference between what customers say they want and what actually makes them happy.', 'Noriaki Kano (1984)', '[3, 4, 5, 6]', '2026-07-10 17:55:46.360166+00', 'A product development model that classifies features into three categories: Basic (must-haves that cause dissatisfaction if missing), Performance (the more the better), and Delight (unexpected features that create loyalty). Helps founders understand what actually drives customer satisfaction.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('31', 'Product', '2026-07-10 17:55:46.360166+00', 'Sean Ellis', 'FW-031', 'Sean Ellis PMF Survey', 'Referenced in intervention for ''Poor Product-Market Fit.'' Used in the Question Bank as a key metric-probing question for product category diagnosis.', '["all"]', '[]', '["RC-373", "RC-374", "RC-375"]', 'Founders who believe they have product-market fit based on anecdotal evidence or their own excitement rather than systematic measurement.', 'Sean Ellis / GrowthHackers (2009)', '[3, 4, 5]', '2026-07-10 17:55:46.360166+00', 'A single-question survey to measure product-market fit: ''How would you feel if you could no longer use this product?'' If 40% or more answer ''Very disappointed,'' the product has reached PMF. Below 40% indicates the product has not yet found its fit.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('32', 'Product', '2026-07-10 17:55:46.360166+00', 'Teresa Torres', 'FW-032', 'Continuous Discovery Habits', 'Referenced in interventions for ''Lack of User Feedback Loop'' and ''Feature Bloat.'' One of the core frameworks for building a sustainable customer learning culture.', '["all"]', '["INT-020", "INT-011"]', '["RC-373", "RC-374", "RC-375"]', 'Founders who do customer research once at the start and then build in isolation. Continuous discovery keeps the product aligned with evolving customer needs.', 'Continuous Discovery Habits — Teresa Torres (2021)', '[3, 4, 5, 6, 7]', '2026-07-10 17:55:46.360166+00', 'A framework for embedding regular customer conversations into the product development process — weekly customer interviews, structured feedback synthesis, and opportunity mapping — rather than doing discovery as a one-time exercise.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('33', 'Product', '2026-07-10 17:55:46.360166+00', 'Google', 'FW-033', 'HEART Framework', 'Referenced in interventions for ''Lack of User Feedback Loop'' and ''Poor User Experience.'' Used in the Question Bank to probe whether founders are tracking the right product metrics.', '["saas"]', '["INT-041", "INT-011"]', '["RC-373", "RC-374", "RC-375"]', 'Founders measuring only revenue or user counts while ignoring engagement, satisfaction, and task completion — missing early warning signs of product-market fit erosion.', 'Google Ventures / Kerry Rodden (2010)', '[3, 4, 5, 6, 7]', '2026-07-10 17:55:46.360166+00', 'A product metrics framework measuring five dimensions: Happiness (user satisfaction), Engagement (depth of interaction), Adoption (new user uptake), Retention (returning users), Task Success (completion of key actions). Provides a balanced view of product performance.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('34', 'Product', '2026-07-10 17:55:46.360166+00', 'Eric Ries', 'FW-034', 'Minimum Viable Product (MVP)', 'One of the most fundamental frameworks in the Founder Ally library. Referenced across multiple categories. Used as the primary intervention for perfectionism and over-engineering root causes.', '["all"]', '["INT-040"]', '["RC-373", "RC-374", "RC-375"]', 'Founders building complete products before validating assumptions. The MVP shifts the question from ''Can we build it?'' to ''Should we build it?''', 'The Lean Startup — Eric Ries (2011)', '[1, 2, 3]', '2026-07-10 17:55:46.360166+00', 'The smallest version of a product that allows the team to collect the maximum amount of validated learning about customers with the least effort. Not a cheap product — a learning instrument.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('35', 'Product', '2026-07-10 17:55:46.360166+00', 'Roman Pichler', 'FW-035', 'Product Vision Board', 'Referenced in intervention for ''No Clear Product Vision.'' Recommended as the first tool when the root cause is reactive development or vision confusion.', '["all"]', '["INT-042"]', '["RC-373", "RC-374", "RC-375"]', 'Founders and teams who are building without a shared product direction — everyone has a different idea of where the product should go next.', 'Roman Pichler (2012)', '[2, 3, 4, 5, 6]', '2026-07-10 17:55:46.360166+00', 'A one-page strategic tool that aligns the team around target users, customer needs, product features, and business goals. Creates a shared understanding of where the product is going and why.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('36', 'Product', '2026-07-10 17:55:46.360166+00', 'Janna Basler / Product community', 'FW-036', 'Now-Next-Later Roadmap', 'Referenced in intervention for ''No Clear Product Vision.'' Provides the practical structure for managing product direction without becoming rigidly committed to a long-term plan that will inevitably change.', '["all"]', '["INT-012"]', '["RC-373", "RC-374", "RC-375"]', 'Founders who either have no roadmap or have overly detailed roadmaps that become obsolete within weeks. The Now-Next-Later format balances structure with flexibility.', 'Janna Basler / ProductPlan', '[2, 3, 4, 5, 6]', '2026-07-10 17:55:46.360166+00', 'A simple roadmap format that organises work into three horizons — what is being built now, what comes next, and what is planned for later — without false precision about dates or specific features far in the future.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('37', 'Product', '2026-07-10 17:55:46.360166+00', 'Dan Olsen', 'FW-037', 'Product-Market Fit Pyramid', 'Referenced in intervention for ''Poor Product-Market Fit.'' Used in the diagnosis to identify which layer of the PMF pyramid is causing the fit problem.', '["all"]', '["INT-043"]', '["RC-373", "RC-374", "RC-375"]', 'Founders who are trying to find PMF by changing features without understanding which layer of the pyramid is actually broken.', 'The Lean Product Playbook — Dan Olsen (2015)', '[2, 3, 4, 5]', '2026-07-10 17:55:46.360166+00', 'A five-layer hierarchy for achieving PMF: Target customer → Underserved needs → Value proposition → Feature set → UX. Each layer must be solved before the one above it. Provides a structured path to finding fit.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('38', 'Team & Leadership', '2026-07-10 17:55:46.360166+00', 'Management 3.0 community', 'FW-038', 'Delegation Ladder (7 Levels)', 'Referenced in intervention for ''Hero Syndrome / Founder Does Everything.'' One of the three immediate next steps for delegation root causes.', '["all"]', '["INT-007"]', '["RC-225", "RC-226", "RC-227"]', 'Founders who either micro-manage everything or delegate without structure — both leading to poor outcomes. The ladder makes delegation a conscious, scalable practice.', 'Management 3.0 — Jurgen Appelo', '[3, 4, 5, 6, 7]', '2026-07-10 17:55:46.360166+00', 'A framework defining seven levels of delegation from ''Do as I say'' through ''Decide and don''t report.'' Each level gives more autonomy and ownership to the team member. Helps founders match the right delegation level to each person and task.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('39', 'Team & Leadership', '2026-07-10 17:55:46.360166+00', 'Geoff Smart & Randy Street', 'FW-039', 'WHO Hiring Method', 'Referenced in intervention for ''Poor Hiring Practices.'' One of the primary recommended frameworks when the root cause is urgency bias or gut-feel hiring.', '["all"]', '["INT-033", "INT-031"]', '["RC-225", "RC-226", "RC-227"]', 'Founders making hiring mistakes because they rely on interviews without a structured evaluation process. Bad hires at early stage can be existential.', 'WHO: The A Method for Hiring — Geoff Smart & Randy', '[3, 4, 5, 6, 7]', '2026-07-10 17:55:46.360166+00', 'A structured hiring methodology using scorecards (defining outcomes before hiring), structured behavioural interviews (A-Method), and deep reference checks. Replaces gut-feel hiring with evidence-based selection.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('40', 'Team & Leadership', '2026-07-10 17:55:46.360166+00', 'Patrick Lencioni', 'FW-040', 'Five Dysfunctions of a Team', 'Referenced across multiple team root causes. Used in the diagnosis to probe co-founder conflicts, team culture problems, and accountability gaps.', '["all"]', '["INT-089", "INT-030"]', '["RC-225", "RC-226", "RC-227"]', 'Teams that appear functional on the surface but are plagued by unspoken conflicts, lack of commitment, and poor accountability. The model reveals which dysfunction is the actual root cause.', 'The Five Dysfunctions of a Team — Patrick Lencioni', '[3, 4, 5, 6, 7]', '2026-07-10 17:55:46.360166+00', 'A model identifying the five root causes of team dysfunction in hierarchy: absence of trust, fear of conflict, lack of commitment, avoidance of accountability, and inattention to results. Each dysfunction builds on the one below it.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('41', 'Team & Leadership', '2026-07-10 17:55:46.360166+00', 'Gino Wickman', 'FW-041', 'EOS — Entrepreneurial Operating System', 'Referenced in interventions for ''Hero Syndrome,'' ''No SOPs,'' and ''No Processes.'' One of the most comprehensive operating system frameworks in the Founder Ally library.', '["all"]', '["INT-050", "INT-007", "INT-093"]', '["RC-225", "RC-226", "RC-227"]', 'Founders who are growing but lack the operational structure to keep everyone aligned and accountable. EOS translates vision into daily execution.', 'Traction — Gino Wickman (2011)', '[4, 5, 6, 7, 8]', '2026-07-10 17:55:46.360166+00', 'A complete business operating system built around six components: Vision, People, Data, Issues, Process, and Traction. Provides a practical system for running a company through Level 10 Meetings, Rocks (quarterly priorities), and Scorecards.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('42', 'Team & Leadership', '2026-07-10 17:55:46.360166+00', 'Ken Blanchard', 'FW-042', 'Situational Leadership II', 'Referenced in interventions for ''Leading Through Managers Instead of Directly'' and ''Trust Enough to Let Go.'' Used in the scaling section for founders transitioning to executive leadership.', '["all"]', '["INT-055", "INT-088"]', '["RC-225", "RC-226", "RC-227"]', 'Leaders who apply the same management style to every team member regardless of their experience or confidence level — leading to under-development of high-potential people and over-support of capable ones.', 'Leadership and the One Minute Manager — Blanchard et', '[4, 5, 6, 7, 8]', '2026-07-10 17:55:46.360166+00', 'A leadership model that matches leadership style (directing, coaching, supporting, delegating) to each team member''s development level (competence and commitment). Recognises that the right leadership approach depends on who you are leading and in what context.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('43', 'Team & Leadership', '2026-07-10 17:55:46.360166+00', 'Project management standard', 'FW-043', 'RACI Matrix', 'One of the most frequently referenced frameworks in the Founder Ally library. Used across Team, Operations, and Scaling categories whenever role ambiguity or accountability gaps are the root cause.', '["all"]', '["INT-090", "INT-089", "INT-076"]', '["RC-225", "RC-226", "RC-227"]', 'Teams and organisations where nobody knows who is responsible for what — leading to duplication, gaps, and finger-pointing when things go wrong.', 'Project management standard — widely attributed to', '[3, 4, 5, 6, 7, 8]', '2026-07-10 17:55:46.360166+00', 'A responsibility assignment matrix that defines who is Responsible (does the work), Accountable (owns the outcome), Consulted (provides input), and Informed (receives updates) for every major task or decision.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('44', 'Team & Leadership', '2026-07-10 17:55:46.360166+00', 'McKinsey / GE', 'FW-044', '9-Box Talent Matrix', 'Referenced in intervention for ''No Plan for Who Comes Next.'' Used in the People Management Complexity section for scaling companies.', '["all"]', '["INT-070"]', '["RC-225", "RC-226", "RC-227"]', 'Leaders who make talent decisions based on recency bias or personal relationships rather than a structured assessment of performance and potential.', 'McKinsey & Company / GE (1970s)', '[5, 6, 7, 8]', '2026-07-10 17:55:46.360166+00', 'A talent assessment tool that plots employees on a 3x3 grid of performance (current results) versus potential (future capability). Creates a visual map of the talent portfolio and guides development, succession, and retention decisions.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('45', 'Team & Leadership', '2026-07-10 17:55:46.360166+00', 'Amy Edmondson', 'FW-045', 'Psychological Safety Framework', 'Referenced in interventions for ''Cultural or Communication Problems'' and ''Office Politics.'' Used in the Founder Behaviour document as a key principle for the empathy framework.', '["all"]', '["INT-074", "INT-008"]', '["RC-225", "RC-226", "RC-227"]', 'Teams where people hold back important information, avoid conflict, and pretend agreement — leading to poor decisions and hidden problems that surface too late.', 'The Fearless Organisation — Amy Edmondson (2018)', '[3, 4, 5, 6, 7, 8]', '2026-07-10 17:55:46.360166+00', 'A research-based model for creating team environments where people can speak up, take risks, and challenge ideas without fear of punishment or embarrassment. Based on research showing psychological safety is the top predictor of team performance.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('46', 'Team & Leadership', '2026-07-10 17:55:46.360166+00', 'Charan, Drotter & Noel', 'FW-046', 'Leadership Pipeline Model', 'Referenced in interventions for ''New Managers Never Actually Trained'' and ''From Doing the Work to Leading the Company.'' Used heavily in the Scaling section.', '["all"]', '["INT-075"]', '["RC-225", "RC-226", "RC-227"]', 'Companies that promote high performers into leadership roles without preparing them for the fundamentally different work of leading others. The model identifies which leadership passage is causing the gap.', 'The Leadership Pipeline — Charan, Drotter & Noel', '[5, 6, 7, 8]', '2026-07-10 17:55:46.360166+00', 'A model describing the six passages leaders must navigate from individual contributor to enterprise leader — each requiring new skills, time applications, and work values. Helps organisations develop leaders systematically at each passage.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('47', 'Fundraising', '2026-07-10 17:55:46.360166+00', 'Sequoia Capital', 'FW-047', 'Sequoia Capital Story Framework', 'Referenced in intervention for ''Unable to Raise Capital.'' The primary pitch narrative framework recommended when the root cause is weak storytelling or poor investor narrative.', '["all"]', '["INT-062", "INT-030", "INT-091"]', '["RC-297", "RC-298", "RC-299"]', 'Founders who have strong businesses but tell weak investment stories. The framework organises the narrative in the order that maximises investor conviction.', 'Sequoia Capital internal framework / widely published', '[3, 4, 5, 6]', '2026-07-10 17:55:46.360166+00', 'A pitch narrative framework covering: company purpose, problem, solution, why now, market size, competition, product, team, business model, and traction. Used by Sequoia to evaluate and improve founder pitches.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('48', 'Fundraising', '2026-07-10 17:55:46.360166+00', 'Guy Kawasaki', 'FW-048', 'Guy Kawasaki 10-20-30 Rule', 'Referenced in intervention for ''Weak Pitch Deck.'' One of the first recommended fixes when the root cause is information overload or unfocused pitch narrative.', '["all"]', '["INT-010"]', '["RC-297", "RC-298", "RC-299"]', 'Founders with 40-slide pitch decks full of small text that investors cannot follow. Simplicity and clarity in pitch decks correlate strongly with investor engagement.', 'The Art of the Start — Guy Kawasaki (2004)', '[3, 4, 5, 6]', '2026-07-10 17:55:46.360166+00', 'A pitch presentation guideline: 10 slides maximum, 20 minutes maximum, 30-point minimum font size. Forces founders to distil their story to what truly matters and present it in a way investors can actually absorb.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('49', 'Fundraising', '2026-07-10 17:55:46.360166+00', 'Venture capital standard', 'FW-049', 'Milestone-Based Fundraising Framework', 'Referenced in interventions for ''Raising Too Little Capital'' and ''Raising Too Much Too Early.'' The core framework for rational fundraising strategy.', '["all"]', '["INT-009"]', '["RC-297", "RC-298", "RC-299"]', 'Founders who raise too little (run out before proving the next milestone) or too much (take unnecessary dilution before the business is ready to deploy capital efficiently).', 'Venture capital best practice / Fred Wilson / A16Z', '[2, 3, 4, 5]', '2026-07-10 17:55:46.360166+00', 'A fundraising approach where the founder raises only enough capital to reach the next major value-inflection milestone — rather than raising the maximum possible or the minimum to survive. Each raise is sized to the next proof point.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('50', 'Fundraising', '2026-07-10 17:55:46.360166+00', 'Founder Ally / GoXL synthesis', 'FW-050', 'Investor Fit Scorecard', 'Referenced in intervention for ''Wrong Investor Fit.'' Recommended as the first step before any fundraising outreach begins.', '["all"]', '["INT-036"]', '["RC-297", "RC-298", "RC-299"]', 'Founders who take meetings with every investor who responds and waste months pitching the wrong people. Investor fit is as important as investor interest.', 'Founder Ally Intervention Library — Doc 8', '[3, 4, 5, 6]', '2026-07-10 17:55:46.360166+00', 'A structured evaluation framework for assessing investor fit before taking meetings. Scores investors on stage preference, sector expertise, value-add beyond capital, decision speed, and founder reputation.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('51', 'Fundraising', '2026-07-10 17:57:13.082473+00', 'Venture capital standard', 'FW-051', 'Bottom-Up Market Sizing', 'Referenced in intervention for ''Weak Pitch Deck.'' Taught as part of the pitch narrative framework. The foundation of a credible investor story.', '["all"]', '["INT-010"]', '["RC-297", "RC-298", "RC-299"]', 'Founders citing vague top-down TAM numbers like ''the Indian EdTech market is worth $10 billion'' without any logic connecting that number to their actual opportunity.', 'Venture capital standard / widely attributed', '[2, 3, 4, 5]', '2026-07-10 17:57:13.082473+00', 'A market sizing methodology that builds TAM, SAM, and SOM from the ground up using unit economics — number of potential customers times average contract value — rather than citing top-down industry reports.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('52', 'Fundraising', '2026-07-10 17:57:13.082473+00', 'Founder Ally / GoXL synthesis', 'FW-052', 'Monthly Investor Update Framework', 'Referenced in intervention for ''Poor Investor Management.'' One of the three immediate next steps when the root cause is reactive investor relations.', '["all"]', '["INT-091", "INT-037"]', '["RC-297", "RC-298", "RC-299"]', 'Founders who only communicate with investors when raising again — destroying trust and missing opportunities for introductions, advice, and support.', 'Founder Ally Intervention Library — Doc 8', '[4, 5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A structured format for monthly investor communications covering: key metrics against targets, milestones achieved, current challenges, specific asks, and financial update. Builds trust and opens doors for additional support.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('53', 'Operations & Systems', '2026-07-10 17:57:13.082473+00', 'Andy Grove / John Doerr', 'FW-053', 'OKRs — Objectives and Key Results', 'One of the most referenced frameworks in the entire Founder Ally library. Used in interventions for ''No Metrics or KPIs'' and ''Founder as Bottleneck.'' Also referenced in cross-category branching rules.', '["all"]', '["INT-069", "INT-095"]', '["RC-445", "RC-446", "RC-447"]', 'Founders and organisations that set vague goals like ''grow the business'' without measurable outcomes. OKRs replace ambiguity with accountability.', 'Measure What Matters — John Doerr (2018)', '[4, 5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A goal-setting framework that connects ambitious qualitative objectives to 3-5 measurable key results. Creates alignment from company level to individual level. Objectives set direction; key results measure progress.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('54', 'Operations & Systems', '2026-07-10 17:57:13.082473+00', 'Financial management standard', 'FW-054', '13-Week Cash Flow Forecast', 'Referenced in multiple interventions across Operations and Financial categories. One of the first tools recommended when cash flow or financial disorganisation is the root cause.', '["all"]', '["INT-039", "INT-062", "INT-094"]', '["RC-445", "RC-446", "RC-447"]', 'Founders who manage cash by checking the bank balance rather than projecting forward. 13 weeks gives enough visibility to respond to problems before they become existential.', 'Financial management best practice / widely attributed', '[3, 4, 5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A rolling weekly cash flow projection covering the next 13 weeks (one quarter). Tracks expected cash inflows and outflows week by week to identify liquidity risks before they become crises.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('55', 'Operations & Systems', '2026-07-10 17:57:13.082473+00', 'Peter Pyhrr', 'FW-055', 'Zero-Based Budgeting', 'Referenced in interventions for ''Financial Disorganisation'' and ''Spending Grows Faster Than Control.'' Used in the Scaling & Operational Maturity section.', '["all"]', '["INT-039", "INT-094", "INT-061"]', '["RC-445", "RC-446", "RC-447"]', 'Founders and scaling companies where spending grows by default rather than by decision. ZBB creates deliberate cost discipline instead of incremental cost drift.', 'Zero-Base Budgeting — Peter Pyhrr (1973)', '[4, 5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A budgeting approach where every expense must be justified from scratch for each period — rather than starting from last period''s budget and making adjustments. Forces discipline around every line of spending.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('56', 'Operations & Systems', '2026-07-10 17:57:13.082473+00', 'Operations management standard', 'FW-056', 'Standard Operating Procedures (SOP) Framework', 'Referenced in interventions for ''No SOPs / Operational Chaos'' and ''Nobody Wrote Anything Down.'' One of the most frequently recommended immediate actions for operations root causes.', '["all"]', '["INT-046", "INT-013"]', '["RC-445", "RC-446", "RC-447"]', 'Founders and teams where critical knowledge lives only in people''s heads. When key people leave or scale creates volume, undocumented processes break.', 'Operations management standard / widely attributed', '[3, 4, 5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A documentation system for recurring processes — step-by-step instructions that allow any trained person to complete the task consistently to the required standard. Converts founder knowledge into organisational knowledge.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('57', 'Operations & Systems', '2026-07-10 17:57:13.082473+00', 'Sean Ellis / growth community', 'FW-057', 'North Star Metric Framework', 'Referenced in interventions for ''No Metrics or KPIs'' and ''Over-Focusing on Acquisition.'' One of the key strategic alignment tools in the Founder Ally framework library.', '["all"]', '["INT-026", "INT-095", "INT-042"]', '["RC-445", "RC-446", "RC-447"]', 'Organisations where different teams optimise different metrics that are not connected to real customer value. Revenue can grow while customer value erodes — the North Star prevents this disconnect.', 'Sean Ellis / GrowthHackers community', '[3, 4, 5, 6, 7]', '2026-07-10 17:57:13.082473+00', 'A framework for identifying the single metric that best captures the core value the product delivers to customers — and aligning the entire organisation around growing it. The North Star prevents the fragmentation that comes from optimising multiple competing metrics.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('58', 'Operations & Systems', '2026-07-10 17:57:13.082473+00', 'Operations management standard', 'FW-058', 'Business Process Mapping (BPM)', 'Referenced in interventions for ''Simple Processes Collapse Under Growth'' and ''No Processes or Ad-Hoc Operations.'' The foundational tool for operational improvement.', '["all"]', '["INT-046"]', '["RC-445", "RC-446", "RC-447"]', 'Founders who cannot identify why processes keep breaking as the team grows. Process mapping makes the invisible visible.', 'Operations management standard / widely attributed', '[4, 5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A method for visually documenting how work flows through an organisation — identifying inputs, outputs, decisions, and handoffs. Reveals inefficiencies, bottlenecks, and gaps that are invisible in verbal descriptions.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('59', 'Operations & Systems', '2026-07-10 17:57:13.082473+00', 'David Sacks', 'FW-059', 'Burn Multiple', 'Referenced in interventions for ''Spending Grows Faster Than Control'' and ''Financial Disorganisation.'' Used in the SaaS industry calibration layer as a key red flag metric.', '["saas"]', '["INT-061", "INT-035"]', '["RC-445", "RC-446", "RC-447"]', 'SaaS founders who are growing revenue but not tracking whether they are burning capital efficiently. High burn multiples signal that growth is being bought, not built.', 'David Sacks / Craft Ventures (2020)', '[4, 5, 6, 7]', '2026-07-10 17:57:13.082473+00', 'A capital efficiency metric that measures how much cash a company burns for every dollar of new ARR added. Burn Multiple = Net Burn / Net New ARR. Lower is better — a Burn Multiple above 2 in early stage is a warning sign.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('60', 'Founder Psychology', '2026-07-10 17:57:13.082473+00', 'Aaron Beck / CBT', 'FW-060', 'Cognitive Restructuring', 'Referenced in intervention for ''Fear of Failure / Imposter Syndrome.'' Used as the primary psychological intervention when the root cause is identity-level thinking distortion.', '["all"]', '["INT-014"]', '["RC-517", "RC-518", "RC-519"]', 'Founders whose decision-making and wellbeing are being undermined by distorted thinking patterns they cannot see. Cognitive restructuring creates the awareness to interrupt these patterns.', 'Cognitive Therapy of Depression — Aaron Beck (1979)', '[1, 2, 3, 4, 5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A psychological technique for identifying and challenging distorted thinking patterns — catastrophising, all-or-nothing thinking, mind-reading — and replacing them with evidence-based alternatives. From Cognitive Behavioural Therapy.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('61', 'Founder Psychology', '2026-07-10 17:57:13.082473+00', 'Gary Klein', 'FW-061', 'Premortem Analysis', 'Referenced in interventions for ''Decision Paralysis / Poor Decision Quality'' and ''Failure to Pivot.'' Also referenced in the Agent Interpretation Table as a probing method for blind spots.', '["all"]', '["INT-002", "INT-016"]', '["RC-517", "RC-518", "RC-519"]', 'Founders who make major decisions while overconfident in their success. The premortem uses prospective hindsight to identify failure modes before they occur.', 'Sources of Power — Gary Klein (1998)', '[2, 3, 4, 5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A decision-making technique where, before a major decision, the team imagines the decision has already failed and works backwards to identify why. Surfaces blind spots and risks that forward-looking planning misses.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('62', 'Founder Psychology', '2026-07-10 17:57:13.082473+00', 'Shane Parrish / Farnam Street', 'FW-062', 'Decision Journal', 'Referenced in interventions for ''Decision Paralysis'' and ''Weak Governance or Oversight.'' One of the three immediate next steps when decision-making quality is the root cause.', '["all"]', '["INT-054", "INT-016", "INT-034"]', '["RC-517", "RC-518", "RC-519"]', 'Founders who do not learn from their decisions because they do not record them. The decision journal creates a feedback loop between decisions and outcomes.', 'Shane Parrish / Farnam Street (widely attributed)', '[1, 2, 3, 4, 5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A personal discipline where the founder records every major decision — the context, the reasoning, the expected outcome, and the alternatives considered — then reviews these entries over time to identify patterns in decision quality.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('63', 'Founder Psychology', '2026-07-10 17:57:13.082473+00', 'Military / Intelligence community', 'FW-063', 'Red-Teaming', 'Referenced in intervention for ''Decision Paralysis / Poor Decision Quality.'' Used alongside the Premortem as a complementary decision quality tool.', '["all"]', '["INT-016"]', '["RC-517", "RC-518", "RC-519"]', 'Founders who surround themselves with people who agree with them. Red-teaming introduces legitimate challenge into the decision process before it is too late to change course.', 'Military and intelligence community standard / widely', '[2, 3, 4, 5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A structured adversarial analysis technique where one person or team is given the explicit role of challenging a decision, plan, or strategy — arguing against it as forcefully as possible to surface weaknesses before commitment.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('64', 'Founder Psychology', '2026-07-10 17:57:13.082473+00', 'Jeff Bezos / Amazon', 'FW-064', 'Two-Way Door Framework', 'Referenced in intervention for ''Decision Paralysis / Poor Decision Quality.'' Used in the diagnosis to probe whether founders understand which of their decisions are actually high-stakes.', '["all"]', '["INT-016"]', '["RC-517", "RC-518", "RC-519"]', 'Founders who apply the same level of analysis to every decision — spending too long on small reversible choices and not enough time on major irreversible ones. Creates decision velocity without recklessness.', 'Jeff Bezos / Amazon shareholder letters', '[1, 2, 3, 4, 5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A decision classification framework that separates reversible decisions (two-way doors — easy to change) from irreversible decisions (one-way doors — very hard to change). Encourages speed on reversible decisions and caution on irreversible ones.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('65', 'Founder Psychology', '2026-07-10 17:57:13.082473+00', 'Christina Maslach', 'FW-065', 'Burnout Stage Assessment', 'Referenced in the Founder Behaviour & Decision Patterns document (Doc 5) and the psychological state scoring system (Doc 10). One of the key frameworks for the Distress Protocol in Doc 12.', '["all"]', '["INT-015"]', '["RC-517", "RC-518", "RC-519"]', 'Founders who cannot tell whether they are tired, burning out, or already burned out. The model provides a diagnostic framework for the burnout trajectory.', 'Maslach Burnout Inventory — Christina Maslach (1981)', '[1, 2, 3, 4, 5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A three-stage model for assessing founder burnout: Stage 1 — Emotional Exhaustion (depleted energy), Stage 2 — Cynicism and Detachment (disengagement), Stage 3 — Ineffectiveness (loss of accomplishment). Each stage has distinct symptoms and requires different interventions.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('66', 'Founder Psychology', '2026-07-10 17:57:13.082473+00', 'Robert Kegan & Lisa Laskow Lahey', 'FW-066', 'Immunity to Change', 'Referenced in intervention for ''A Real Identity Shift Happens'' (Founder Leadership Evolution section). Used when root causes involve deep behavioural patterns that resist surface-level interventions.', '["all"]', '["INT-092"]', '["RC-517", "RC-518", "RC-519"]', 'Founders who know what they need to do differently but cannot seem to do it — not because of capability gaps but because of hidden competing commitments.', 'Immunity to Change — Kegan & Lahey (2009)', '[1, 2, 3, 4, 5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A change framework that reveals the hidden psychological commitments that keep founders stuck despite their best intentions. The Immunity Map identifies the gap between what someone wants to change and what they are unconsciously doing to prevent change.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('67', 'Founder Psychology', '2026-07-10 17:57:13.082473+00', 'Tina Seelig / Stanford', 'FW-067', 'Failure CV Exercise', 'Referenced in intervention for ''Fear of Failure / Imposter Syndrome.'' One of the three immediate next steps for identity-related root causes.', '["all"]', '["INT-014"]', '["RC-517", "RC-518", "RC-519"]', 'Founders who are avoiding action because they are catastrophising potential failure. The Failure CV reframes the relationship between founder identity and failure.', 'Tina Seelig / Stanford d.school (widely attributed)', '[1, 2, 3, 4, 5]', '2026-07-10 17:57:13.082473+00', 'A reflective exercise where the founder writes a reverse CV documenting their failures, rejections, and setbacks — alongside what each one taught them. Normalises failure as data rather than identity.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('68', 'Scaling & Growth', '2026-07-10 17:57:13.082473+00', 'McKinsey & Company', 'FW-068', 'Three Horizons Framework', 'Referenced in interventions for ''Balancing Today and Tomorrow'' and ''Staying Innovative While Organised.'' One of the core strategic frameworks for scaling companies.', '["all"]', '["INT-093"]', '["RC-661", "RC-662", "RC-663"]', 'Scaling founders who are so focused on today''s fires that they neglect the investments needed for tomorrow''s growth. The Three Horizons creates structural time for strategic thinking.', 'McKinsey & Company / Baghai, Coley & White (1999)', '[5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A strategic planning framework that allocates attention and resources across three time horizons simultaneously: Horizon 1 (core business — next 1-2 years), Horizon 2 (emerging opportunities — 2-5 years), Horizon 3 (future bets — 5+ years). Prevents short-term thinking from destroying long-term potential.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('69', 'Scaling & Growth', '2026-07-10 17:57:13.082473+00', 'W. Chan Kim & Renée Mauborgne', 'FW-069', 'Blue Ocean Strategy', 'Referenced in interventions for ''Competitors Show Up Fast'' and ''The Market Gets Crowded.'' Used in competitive strategy diagnosis for scaling companies.', '["all"]', '["INT-017", "INT-078", "INT-081"]', '["RC-661", "RC-662", "RC-663"]', 'Founders competing on existing dimensions in crowded markets where the only variable is price. Blue Ocean Strategy reveals how to create new value that competitors cannot immediately copy.', 'Blue Ocean Strategy — Kim & Mauborgne (2005)', '[3, 4, 5, 6, 7]', '2026-07-10 17:57:13.082473+00', 'A strategy framework for creating uncontested market space by making the competition irrelevant — rather than competing in existing saturated markets. Distinguishes between red oceans (competitive markets) and blue oceans (new value-cost trade-offs).') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('70', 'Scaling & Growth', '2026-07-10 17:57:13.082473+00', 'Michael Porter', 'FW-070', E'Porter\\''s Generic Strategies', 'Referenced in intervention for ''Competitors Show Up Fast.'' Used in the competitive strategy diagnosis for companies facing increasing market pressure.', '["all"]', '["INT-078"]', '["RC-661", "RC-662", "RC-663"]', 'Founders who are trying to be everything to everyone — affordable AND premium AND broad AND niche. The framework forces a strategic choice.', 'Competitive Strategy — Michael Porter (1980)', '[4, 5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'Three strategies for achieving sustainable competitive advantage: Cost Leadership (lowest cost producer), Differentiation (unique value that commands premium), and Focus (serving a narrow segment better than anyone). Being stuck in the middle — none of the three — is the most dangerous position.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('71', 'Scaling & Growth', '2026-07-10 17:57:13.082473+00', 'Pankaj Ghemawat', 'FW-071', 'CAGE Distance Framework', 'Referenced in intervention for ''Going International Brings a Whole New Set of Competitors.'' Used in the international expansion section of the Scaling category.', '["all"]', '["INT-086"]', '["RC-661", "RC-662", "RC-663"]', 'Founders who assume markets that look similar on the surface will behave similarly. The CAGE framework reveals hidden distances that determine whether expansion will succeed.', 'Redefining Global Strategy — Pankaj Ghemawat (2007)', '[6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A framework for evaluating international market entry by assessing four types of distance: Cultural, Administrative, Geographic, and Economic. Helps founders avoid the most common international expansion mistakes.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('72', 'Scaling & Growth', '2026-07-10 17:57:13.082473+00', 'Geoffrey Parker & Marshall Van Alstyne', 'FW-072', 'Platform Strategy Framework', 'Referenced in intervention for ''Bigger Platforms Can Box You Out.'' Used in the competitive defensibility diagnosis for marketplace and platform businesses.', '["all"]', '["INT-083"]', '["RC-661", "RC-662", "RC-663"]', 'Platform founders who apply linear business thinking to platform problems — treating the platform like a product company and missing the network effects that determine platform success or failure.', 'Platform Revolution — Parker, Van Alstyne & Choudary', '[4, 5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A strategic framework for businesses that create value by facilitating interactions between two or more user groups. Covers network effects, platform design, ecosystem development, and competitive dynamics unique to platform businesses.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('73', 'Scaling & Growth', '2026-07-10 17:57:13.082473+00', 'O''Reilly & Tushman', 'FW-073', 'Ambidextrous Organisation Framework', 'Referenced in intervention for ''Staying Innovative While Also Staying Organised.'' Used in the Founder Leadership Evolution section for Stage 7-9 founders.', '["all"]', '["INT-093"]', '["RC-661", "RC-662", "RC-663"]', 'Scaling founders who must optimise the current business while also innovating for the future — two activities that naturally conflict with each other.', 'Lead and Disrupt — O''Reilly & Tushman (2016)', '[6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A management framework for simultaneously exploiting current business strengths (exploitation) while exploring future opportunities (exploration). Structural and contextual approaches to building ambidexterity.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('74', 'Scaling & Growth', '2026-07-10 17:57:13.082473+00', 'Andrew Chen / NFX', 'FW-074', 'Network Effects Framework', 'Referenced in intervention for ''Bigger Platforms Can Box You Out.'' Used in the competitive moat diagnosis for network-effect businesses.', '["all"]', '["INT-083"]', '["RC-661", "RC-662", "RC-663"]', 'Founders who know they have network effects but do not understand how to strengthen them or defend against competitors who are trying to break them.', 'Andrew Chen / NFX / James Currier', '[3, 4, 5, 6, 7]', '2026-07-10 17:57:13.082473+00', 'A framework for understanding, designing, and strengthening network effects — where the product becomes more valuable as more people use it. Classifies network effects by type (direct, indirect, data, social, marketplace) and strength.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('75', 'Scaling & Growth', '2026-07-10 17:57:13.082473+00', 'Hamilton Helmer', 'FW-075', '7 Powers Framework', 'Referenced in intervention for ''The Original Advantage Stops Protecting You.'' Used in the competitive defensibility diagnosis for scaling companies.', '["all"]', '["INT-079"]', '["RC-661", "RC-662", "RC-663"]', 'Founders who cannot articulate what makes their competitive advantage durable. The 7 Powers framework reveals whether the moat is real or imaginary.', '7 Powers: The Foundations of Business Strategy —', '[4, 5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A framework identifying the seven sources of sustainable competitive advantage: Scale Economies, Network Effects, Counter-Positioning, Switching Costs, Branding, Cornered Resource, and Process Power. Each power must be earned and maintained.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('76', 'Financial & Revenue', '2026-07-10 17:57:13.082473+00', 'Corporate finance standard', 'FW-076', 'Financial Planning & Analysis (FP&A)', 'Referenced in intervention for ''No Real Financial Planning System.'' Recommended when the root cause is spreadsheet dependence or reactive financial management.', '["all"]', '["INT-067"]', '["RC-694", "RC-695", "RC-696"]', 'Founders who are reactive about finances — looking at what happened rather than planning for what will happen. FP&A replaces financial surprise with financial foresight.', 'Corporate finance standard / widely attributed', '[5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A business function and set of practices covering financial forecasting, budgeting, performance analysis, and management reporting. FP&A connects financial data to strategic decision-making.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('77', 'Financial & Revenue', '2026-07-10 17:57:13.082473+00', 'FP&A best practice', 'FW-077', 'Driver-Based Financial Model', 'Referenced in intervention for ''No Real Financial Planning System.'' The recommended approach for replacing static spreadsheets with a living financial model.', '["all"]', '["INT-067"]', '["RC-694", "RC-695", "RC-696"]', 'Founders who build financial models by extrapolating from past numbers without understanding the drivers that create those numbers. Driver-based models reveal which levers actually move the financial needle.', 'FP&A best practice / widely attributed', '[4, 5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A financial model built from operational drivers — number of customers, average deal size, churn rate, headcount, pricing — rather than from historical trends. Connects business actions directly to financial outcomes.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('78', 'Financial & Revenue', '2026-07-10 17:57:13.082473+00', 'Managerial accounting standard', 'FW-078', 'Contribution Margin Analysis', 'Referenced in interventions for ''Profit Margins Quietly Shrink'' and ''Pricing vs Cost Confusion.'' Used in the Manufacturing/D2C and Services industry calibration layers.', '["all"]', '["INT-063", "INT-027"]', '["RC-694", "RC-695", "RC-696"]', 'Founders who track total revenue without understanding which customers, products, or services are profitable. Contribution margin reveals where money is being made and where it is being lost.', 'Managerial accounting standard / widely attributed', '[3, 4, 5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A profitability analysis that measures revenue minus variable costs for each product, customer segment, or service line. Reveals which parts of the business are actually contributing to covering fixed costs and generating profit.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('79', 'Financial & Revenue', '2026-07-10 17:57:13.082473+00', 'Corporate finance standard', 'FW-079', 'Cash Conversion Cycle (CCC)', 'Referenced in intervention for ''Cash Gets Tied Up Unexpectedly.'' Used in the Manufacturing & D2C industry calibration layer as a key operational metric.', '["all"]', '["INT-062"]', '["RC-694", "RC-695", "RC-696"]', 'Manufacturing and services founders who are profitable on paper but cash-poor in reality. The CCC reveals where cash is getting trapped in the business cycle.', 'Corporate finance standard / widely attributed', '[4, 5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A metric measuring how long it takes cash to flow from investment in inputs to collection from customers: Days Inventory Outstanding + Days Sales Outstanding - Days Payable Outstanding. Lower CCC means cash flows faster.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('80', 'Financial & Revenue', '2026-07-10 17:57:13.082473+00', 'SaaS / subscription standard', 'FW-080', 'Net Revenue Retention (NRR)', 'Referenced extensively in the SaaS industry calibration layer (Doc 9). One of the key red flag metrics — SaaS NRR below 100% is a critical signal in the diagnosis.', '["all"]', '["INT-066"]', '["RC-694", "RC-695", "RC-696"]', 'SaaS founders who celebrate revenue growth without realising their existing customer base is actually shrinking — masked by new customer acquisition. NRR is the most important health metric for subscription businesses.', 'SaaS / subscription industry standard', '[4, 5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A metric measuring revenue retained from existing customers over a period — including expansion, contraction, and churn. NRR above 100% means the business grows even with zero new customers. NRR below 100% means existing customer revenue is shrinking.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('81', 'Financial & Revenue', '2026-07-10 17:57:13.082473+00', 'Royal Dutch Shell / strategy community', 'FW-081', 'Scenario Planning Framework', 'Referenced in multiple interventions across Fundraising and Financial categories. Used when the root cause involves revenue forecasting or capital planning assumptions.', '["all"]', '["INT-009", "INT-044"]', '["RC-694", "RC-695", "RC-696"]', 'Founders who plan based on their most optimistic assumptions and have no response prepared when reality diverges. Scenario planning builds strategic resilience.', 'Royal Dutch Shell (1970s) / widely adopted in strategy', '[4, 5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A strategic planning method that prepares organisations for multiple possible futures rather than betting on a single forecast. Typically models best-case, expected-case, and downside scenarios across key business variables.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('82', 'Financial & Revenue', '2026-07-10 17:57:13.082473+00', 'NGO / social sector standard', 'FW-082', 'Donor Concentration & 80G Framework', 'Referenced in the Social Impact & NGO industry calibration layer (Doc 9). The donor concentration threshold (above 50% from single donor) is a critical red flag in the NGO diagnosis.', '["all"]', '[]', '["RC-694", "RC-695", "RC-696"]', 'Indian NGO founders who are existentially dependent on 1-2 large donors — typically CSR funders — with no diversification strategy. 80G status is a key enabler of domestic fundraising.', 'Indian NGO / FCRA regulatory framework / CAF India', '[2, 3, 4, 5, 6]', '2026-07-10 17:57:13.082473+00', 'A financial risk framework specific to NGOs and social enterprises assessing donor concentration risk (% of funding from single donors) and the strategic value of 80G tax exemption status for increasing donation attractiveness in India.') on conflict do nothing;
insert into "frameworks" ("framework_id", "category", "created_at", "creator", "framework_code", "framework_name", "how_alley_uses_it", "industry_relevance", "linked_intervention_ids", "linked_root_cause_ids", "problem_it_solves", "source_reference", "stage_relevance", "updated_at", "what_it_is") values ('83', 'Financial & Revenue', '2026-07-10 17:57:13.082473+00', 'Francis Aguilar', 'FW-083', 'PESTLE Analysis', 'Referenced in interventions for ''Product Mis-Timing'' and ''Going International.'' Used as a market readiness assessment tool in the competitive strategy diagnosis.', '["all"]', '["INT-086", "INT-044"]', '["RC-694", "RC-695", "RC-696"]', 'Founders who make strategic decisions without understanding the external forces shaping their market. Particularly important for businesses affected by regulation, market cycles, or technology shifts.', 'Environmental Scanning — Francis Aguilar (1967)', '[4, 5, 6, 7, 8]', '2026-07-10 17:57:13.082473+00', 'A strategic environmental scanning framework analysing six external factors: Political, Economic, Social, Technological, Legal, and Environmental. Used for understanding the macro context in which the business operates.') on conflict do nothing;
